// ============================================================
// Lê a saída do silencedetect e monta o comando ffmpeg que
// remove os silêncios do vídeo de origem numa única passada.
//
// Feito ANTES da transcrição: assim os timestamps do Whisper já
// nascem no tempo real (sem silêncio) e a duração mínima dos
// cortes passa a ser tempo de fala de verdade.
// ============================================================

// --- ajustes ------------------------------------------------
const MARGEM = 0.15;       // segundos de silêncio mantidos em cada ponta (respiro)
const MAX_TRECHOS = 220;   // teto de trechos, pra não estourar o comando
const MIN_TRECHO = 0.25;   // descarta trecho menor que isso (ruído solto)
// Trava de segurança: se fosse cortar mais que isso, algo está errado
// (limiar mal calibrado, áudio muito baixo) e é melhor não cortar nada.
const LIMITE_SEGURANCA = 40;  // em % da duração
// Vídeo muito longo: as duas passadas de ffmpeg travariam o worker por muito tempo.
// Acima disso, segue sem cortar silêncio.
const MAX_MINUTOS = 75;
// ------------------------------------------------------------

const PASTA = '/home/node/files';
const videoId = $('Drive: novo vídeo').first().json.id;
const entrada = `${PASTA}/${videoId}.mp4`;
const saida = `${PASTA}/${videoId}_tight.mp4`;

// O silencedetect escreve no stderr
const bruto = ($json.stderr || '') + '\n' + ($json.stdout || '');

// Duração total do vídeo (vem do "time=" da última linha de progresso)
let duracaoTotal = 0;
for (const m of bruto.matchAll(/time=(\d+):(\d+):([\d.]+)/g)) {
  const t = Number(m[1]) * 3600 + Number(m[2]) * 60 + Number(m[3]);
  if (t > duracaoTotal) duracaoTotal = t;
}
if (!duracaoTotal) {
  throw new Error('Não consegui ler a duração do vídeo na saída do ffmpeg.');
}

// Pares de silêncio
const inicios = [...bruto.matchAll(/silence_start:\s*([\d.]+)/g)].map(m => Number(m[1]));
const fins = [...bruto.matchAll(/silence_end:\s*([\d.]+)/g)].map(m => Number(m[1]));

const silencios = [];
for (let i = 0; i < inicios.length; i++) {
  // Se o vídeo termina em silêncio, não vem o silence_end correspondente
  const fim = i < fins.length ? fins[i] : duracaoTotal;
  silencios.push([inicios[i], fim]);
}

// Vídeo longo demais para as duas passadas: segue sem cortar
if (duracaoTotal > MAX_MINUTOS * 60) {
  return [{
    json: {
      houve_corte: false,
      motivo: `vídeo de ${(duracaoTotal / 60).toFixed(0)}min passa do teto de ${MAX_MINUTOS}min — ` +
              `o corte de silêncio ficaria lento demais no worker`,
      arquivo_final: entrada,
      duracao_antes: +duracaoTotal.toFixed(2),
      duracao_depois: +duracaoTotal.toFixed(2),
      percentual_cortado: 0,
      comando_ffmpeg: `echo "corte de silencio ignorado: video muito longo"`
    }
  }];
}

// Sem silêncio detectado: segue com o arquivo original, sem gastar encode
if (!silencios.length) {
  return [{
    json: {
      houve_corte: false,
      arquivo_final: entrada,
      duracao_antes: +duracaoTotal.toFixed(2),
      duracao_depois: +duracaoTotal.toFixed(2),
      comando_ffmpeg: `echo "sem silencio detectado, mantendo ${entrada}"`
    }
  }];
}

// Monta os trechos a MANTER (o inverso dos silêncios), com margem
const manter = [];
let cursor = 0;
for (const [si, sf] of silencios) {
  const fimTrecho = Math.min(si + MARGEM, duracaoTotal);
  if (fimTrecho - cursor >= MIN_TRECHO) manter.push([cursor, fimTrecho]);
  cursor = Math.max(0, sf - MARGEM);
}
if (duracaoTotal - cursor >= MIN_TRECHO) manter.push([cursor, duracaoTotal]);

// Junta trechos que ficaram colados (a margem pode ter fechado o buraco)
const juntos = [];
for (const t of manter) {
  const ult = juntos[juntos.length - 1];
  if (ult && t[0] - ult[1] < 0.05) ult[1] = t[1];
  else juntos.push([...t]);
}

if (juntos.length > MAX_TRECHOS) {
  throw new Error(
    `${juntos.length} trechos passariam do teto de ${MAX_TRECHOS}. ` +
    `Aumente MARGEM ou o "d=" do silencedetect para agrupar mais.`
  );
}

const duracaoDepois = juntos.reduce((s, [a, b]) => s + (b - a), 0);
const percentual = 100 * (1 - duracaoDepois / duracaoTotal);

// Cortar demais é sinal de problema, não de eficiência
if (percentual > LIMITE_SEGURANCA) {
  return [{
    json: {
      houve_corte: false,
      motivo: `cortaria ${percentual.toFixed(1)}% do vídeo (teto de ${LIMITE_SEGURANCA}%) — ` +
              `provavelmente o áudio está baixo ou o limiar de dB está errado`,
      arquivo_final: entrada,
      duracao_antes: +duracaoTotal.toFixed(2),
      duracao_depois: +duracaoTotal.toFixed(2),
      percentual_cortado: 0,
      comando_ffmpeg: `echo "corte de silencio ignorado: cortaria ${percentual.toFixed(1)}%"`
    }
  }];
}

// Uma passada só: select/aselect com as janelas, e setpts pra recolar o tempo
const expr = juntos
  .map(([a, b]) => `between(t,${a.toFixed(3)},${b.toFixed(3)})`)
  .join('+');

const comando =
  `ffmpeg -y -i ${entrada} ` +
  `-vf "select='${expr}',setpts=N/FRAME_RATE/TB" ` +
  `-af "aselect='${expr}',asetpts=N/SR/TB" ` +
  `-c:v libx264 -preset veryfast -crf 23 -pix_fmt yuv420p ` +
  `-c:a aac -b:a 128k ${saida} && mv -f ${saida} ${entrada}`;

return [{
  json: {
    houve_corte: true,
    arquivo_final: entrada,
    trechos: juntos.length,
    silencios_removidos: silencios.length,
    duracao_antes: +duracaoTotal.toFixed(2),
    duracao_depois: +duracaoDepois.toFixed(2),
    segundos_cortados: +(duracaoTotal - duracaoDepois).toFixed(2),
    percentual_cortado: +percentual.toFixed(1),
    comando_ffmpeg: comando
  }
}];
